<?php
namespace App\Services;
use App\Models\IntegrationSetting;use App\Models\OutboundMessage;use Illuminate\Support\Facades\Crypt;use Illuminate\Support\Facades\Http;use Illuminate\Support\Str;use RuntimeException;
class TwilioSmsService{public function send(int$organizationId,string$to,string$body,?OutboundMessage$message=null):string{$setting=IntegrationSetting::where('organization_id',$organizationId)->where('provider','twilio')->where('active',true)->first();if(!$setting)throw new RuntimeException('Twilio er ikke konfigurert.');$credentials=json_decode(Crypt::decryptString($setting->encrypted_credentials),true,512,JSON_THROW_ON_ERROR);$recipient=$this->normalizeNumber($to);$sender=trim((string)($credentials['from']??''));$payload=['To'=>$recipient,'Body'=>$body];if($message){$token=Str::random(64);$message->update(['delivery_token_hash'=>hash('sha256',$token)]);$payload['StatusCallback']=route('webhooks.twilio.status',['message'=>$message->public_id,'token'=>$token]);}if(str_starts_with($sender,'MG'))$payload['MessagingServiceSid']=$sender;else$payload['From']=$sender;$response=Http::asForm()->withBasicAuth($credentials['api_key'],$credentials['api_secret'])->timeout(15)->post('https://api.twilio.com/2010-04-01/Accounts/'.rawurlencode($credentials['account_sid']).'/Messages.json',$payload);if(!$response->successful())throw new RuntimeException('SMS-leverandøren avviste meldingen (HTTP '.$response->status().'). Kontroller Twilio-oppsettet og at mottakeren kan nås fra kontoen.');return(string)$response->json('sid');}public function normalizeNumber(string$number):string{$number=preg_replace('/[\s().-]+/','',trim($number));if(str_starts_with($number,'00'))$number='+'.substr($number,2);if(preg_match('/^\d{8}$/',$number))$number='+47'.$number;if(!preg_match('/^\+[1-9]\d{7,14}$/',$number))throw new RuntimeException('Mobilnummeret må være norsk 8-sifret nummer eller E.164-format, for eksempel +4799999999.');return$number;}}
